This Terraform configuration creates an AWS Kinesis Data Stream and manages a Kinesis Stream Consumer for it using `aws_kinesis_stream_consumer`. The stream consumer enables enhanced fan-out consumption from the Kinesis stream.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "kinesis_stream_name" {
  description = "Name of the Kinesis Data Stream."
  type        = string
  default     = "example-kinesis-stream"
}

variable "kinesis_consumer_name" {
  description = "Name of the Kinesis Stream Consumer."
  type        = string
  default     = "example-kinesis-consumer"
}

resource "aws_kinesis_stream" "example" {
  name             = var.kinesis_stream_name
  shard_count      = 1
  retention_period = 24

  stream_mode_details {
    stream_mode = "PROVISIONED"
  }

  tags = {
    Name        = var.kinesis_stream_name
    Environment = "example"
    ManagedBy   = "terraform"
  }
}

